\For{$j=1,\dots,j_{\max}$}
  \State $\rho_{\rm low}\gets \rho_{\rm up}/2$
  \If{$p(\rho_{\rm low})\le 0$ \textbf{and} $q(\rho_{\rm low})<1$}
    \State \textbf{break}
  \Else
    \State $\rho_{\rm up}\gets \rho_{\rm low}$ \Comment{still inadmissible; shrink further}
  \EndIf
\EndFor
